  const side=(collapsed,width)=>({collapsed,width,serializeSidebar(){return{collapsed:this.collapsed,width:this.width};},restore(value){this.collapsed=value.collapsed;this.width=value.width;}}),recent=['Source.md','Board.canvas'];
  const w=f.app.workspace={activeLeaf:source,lastFile:'Board.canvas',leftSplit:side(false,260),rightSplit:side(true,240),viewOptions:new Map([['sidebars',{left:'file-explorer',right:'outline'}]]),recentFiles:{serialize:()=>[...recent],load(value){recent.splice(0,recent.length,...value);}},getLeafById:id=>id==='fixture'?f.leaf:id==='source'?source:null,
    getLayout(){return{active:this.activeLeaf.id,sourceParent:source.parent===sourceParent?'original':'folded',sourceTabs:sourceParent.children.map(l=>l.id),boardTabs:boardParent.children.map(l=>l.id),sourceCurrent:sourceParent.currentTab,boardCurrent:boardParent.currentTab,left:this.leftSplit.serializeSidebar(),right:this.rightSplit.serializeSidebar(),camera:structuredClone(f.board.camera),sidebars:this.viewOptions.get('sidebars')};},
    snapshotTree(){const active=this.activeLeaf,sp=source.parent,bp=f.leaf.parent,st=[...sourceParent.children],bt=[...boardParent.children],sc=sourceParent.currentTab,bc=boardParent.currentTab;return()=>{events.push('restore');source.parent=sp;f.leaf.parent=bp;sourceParent.children.splice(0,sourceParent.children.length,...st);boardParent.children.splice(0,boardParent.children.length,...bt);sourceParent.currentTab=sc;boardParent.currentTab=bc;this.activeLeaf=active;};},
    moveLeaf(leaf,parent,index){assert.equal(leaf,source);assert.equal(parent,boardParent);assert.equal(session.dirty,false);assert.equal(f.view.isDirty,false);events.push('move');leaf.parent.children.splice(leaf.parent.children.indexOf(leaf),1);parent.children.splice(index,0,leaf);leaf.parent=parent;parent.currentTab=index;this.activeLeaf=leaf;this.lastFile='Source.md';recent.push('Source.md');return true;},
    setActiveLeaf(leaf,options){assert.equal(leaf,f.leaf);assert.equal(options.focus,false);assert.deepEqual(Object.keys(options),['focus']);events.push('set-active-without-save');this.activeLeaf=leaf;leaf.parent.currentTab=leaf.parent.children.indexOf(leaf);},activateLeaf(){throw Error('Dirty Canvas must not use saving tab activation');},saveAll(){throw Error('Narrow fixture must not save live owners');}};
  f.app.plugins={modules:{'@codemirror/commands':{undoDepth:()=>2,redoDepth:()=>1}}};f.app.sidebars={preferred:{left:'file-explorer',right:'outline'},update(){events.push('sidebar-update');}};
  const context=createContext({app:f.app,crypto:webcrypto,canvasVirtualizationTrace:f.trace}),tools={report:{},async evaluate(code){const result=await new Script(code).runInContext(context),wire=result===undefined?undefined:JSON.stringify(result);if(wire)assert.ok(wire.length<2500,'Only primitive owner/layout receipts cross CDP');return wire===undefined?undefined:JSON.parse(wire);},async click(selector){assert.equal(selector,'[aria-label="Toggle left sidebar"]');events.push('trusted-sidebar-toggle');w.leftSplit.collapsed=true;},async wait(code){assert.equal(Boolean(await new Script(code).runInContext(context)),true);}};
  await helper.rememberSource(tools);w.activeLeaf=f.leaf;const before=await helper.snapshot(tools,'fixture'),layout=JSON.stringify(w.getLayout()),camera=structuredClone(f.board.camera);
  await helper.prepareReadableNarrow(tools,'fixture');assert.equal(source.parent,boardParent);assert.equal(boardParent.children[boardParent.currentTab],f.leaf);assert.equal(w.activeLeaf,f.leaf);assert.equal(w.leftSplit.collapsed,true);assert.equal(context.canvasVirtualizationNarrow.canvas,f.board);assert.equal(context.canvasVirtualizationNarrow.view.leaf,f.leaf);helper.modelExact(before,await helper.snapshot(tools,'fixture'));
  f.board.camera={x:900,y:100,scale:1};await helper.restoreReadableNarrow(tools);assert.equal(source.parent,sourceParent);assert.equal(f.leaf.parent,boardParent);assert.deepEqual(f.board.camera,camera);assert.equal(JSON.stringify(w.getLayout()),layout);assert.deepEqual(recent,['Source.md','Board.canvas']);assert.equal(session.document,sourceDocument);assert.equal(session.text,'# Original Source λ\r\n');assert.equal(session.dirty,false);assert.equal(f.view.isDirty,false);assert.equal(context.canvasVirtualizationSource.cm,cm);assert.equal(Object.hasOwn(context,'canvasVirtualizationNarrow'),false);helper.modelExact(before,await helper.snapshot(tools,'fixture'));assert.equal(f.trace.writes.length,0);assert.deepEqual(events,['trusted-sidebar-toggle','move','set-active-without-save','sidebar-update','restore']);
